function renderCalendar(){const y=calendarMonth.getFullYear(),m=calendarMonth.getMonth();$('#month-label').textContent=`${y} 年 ${m+1} 月`;const first=(new Date(y,m,1).getDay()+6)%7,days=new Date(y,m+1,0).getDate();let html='';for(let i=0;i<first;i++)html+='<button class="blank"></button>';for(let d=1;d<=days;d++){const dt=new Date(y,m,d),key=dateKey(dt),has=state.records.some(r=>dateKey(r.end)===key);html+=`<button data-day="${d}" class="${key===dateKey(new Date())?'today ':''}${key===dateKey(selectedDate)?'selected ':''}${has?'has-data':''}">${d}</button>`}$('#calendar').innerHTML=html;$$('[data-day]').forEach(b=>b.onclick=()=>{selectedDate=new Date(y,m,+b.dataset.day);renderCalendar();renderTimeline()})}
