function renderTimeline(){const rs=state.records.filter(r=>dateKey(r.end)===dateKey(selectedDate)).sort((a,b)=>b.start-a.start),today=dateKey(selectedDate)===dateKey(new Date());$('#timeline-date').textContent=today?'今日记录':`${selectedDate.getMonth()+1} 月 ${selectedDate.getDate()} 日记录`;$('#timeline-total').textContent=rs.length?`共 ${formatDuration(rs.reduce((a,r)=>a+r.duration,0))}`:'';const grouped={};rs.forEach(record=>(grouped[record.task]||(grouped[record.task]=[])).push(record));const summaries=Object.entries(grouped).sort((a,b)=>b[1].reduce((sum,item)=>sum+item.duration,0)-a[1].reduce((sum,item)=>sum+item.duration,0));$('#timeline-summary').innerHTML=summaries.map(([task,items],index)=>{const key=`${dateKey(selectedDate)}:${task}`,open=expandedTimelineTasks.has(key),total=items.reduce((sum,item)=>sum+item.duration,0);return`<article class="timeline-summary-card ${open?'open':''}" data-summary-index="${index}"><button class="timeline-summary-toggle" type="button"><span><b>${escapeHtml(task)}</b><small>${formatDuration(total)}</small></span><i>${open?'⌄':'›'}</i></button><div class="timeline-summary-details">${items.map(item=>`<button type="button" data-record-id="${item.id}"><span><b>${escapeHtml(task)}</b><small>${timelineClock(item.start)} – ${timelineClock(item.end)}</small></span><strong>${formatDuration(item.duration)}</strong></button>`).join('')}</div></article>`}).join('');$$('.timeline-summary-card').forEach(card=>{const [task]=summaries[Number(card.dataset.summaryIndex)],key=`${dateKey(selectedDate)}:${task}`;$('.timeline-summary-toggle',card).onclick=()=>{expandedTimelineTasks.has(key)?expandedTimelineTasks.delete(key):expandedTimelineTasks.add(key);renderTimeline()};$$('.timeline-summary-details [data-record-id]',card).forEach(button=>button.onclick=()=>openTimelineEdit(button.dataset.recordId))});$('#timeline-list').innerHTML=rs.length?rs.map(r=>`<article class="record" data-record-id="${r.id}"><div class="record-time">${new Date(r.start).toLocaleTimeString('zh',{hour:'2-digit',minute:'2-digit'})}</div><div class="record-line"></div><button class="record-card" type="button"><b>${escapeHtml(r.task)}</b><p>${new Date(r.start).toLocaleTimeString('zh',{hour:'2-digit',minute:'2-digit'})} – ${new Date(r.end).toLocaleTimeString('zh',{hour:'2-digit',minute:'2-digit'})} · ${formatDuration(r.duration)}</p><small>点击编辑时间</small></button></article>`).join(''):'<div class="empty"><div>🍃</div><b>这一天很安静</b><p>还没有专注记录</p></div>';$$('.record[data-record-id] .record-card').forEach(card=>card.onclick=()=>openTimelineEdit(card.closest('.record').dataset.recordId))}
function timelineClock(timestamp){const d=new Date(timestamp);return`${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`}
function timelineTimestamp(clock){const parts=clock.split(':').map(Number);if(parts.length!==2||parts.some(Number.isNaN))return NaN;const date=new Date(selectedDate);date.setHours(parts[0],parts[1],0,0);return date.getTime()}
function timelineCandidate(){const record=state.records.find(item=>item.id===timelineEditingId),start=timelineTimestamp($('#timeline-edit-start').value),end=timelineTimestamp($('#timeline-edit-end').value);if(!record||!Number.isFinite(start)||!Number.isFinite(end))return null;const duration=Math.round((end-start)/60000);return{record,start,end,duration,invalidOrder:duration<1}}
function validateTimelineEdit(showError=true){const candidate=timelineCandidate(),errorBox=$('#timeline-edit-error');let message='';if(!candidate)message='请输入正确的开始时间和结束时间。';else if(candidate.invalidOrder)message='结束时间必须晚于开始时间，且记录不能跨越到第二天。';else if(candidate.duration>1439)message='单条专注记录不能超过一天。';else{const conflict=state.records.find(item=>item.id!==timelineEditingId&&candidate.start<item.end&&candidate.end>item.start);if(conflict)message=`与“${conflict.task}”的 ${timelineClock(conflict.start)}–${timelineClock(conflict.end)} 时间重叠。`}if(candidate&&!candidate.invalidOrder){$('#timeline-edit-duration').value=candidate.duration;$('#timeline-edit-preview').textContent=`调整后：${timelineClock(candidate.start)} – ${timelineClock(candidate.end)} · ${formatMinutes(candidate.duration)}`}else $('#timeline-edit-preview').textContent='';errorBox.textContent=message;errorBox.classList.toggle('hidden',!message);return message?null:candidate}
function syncTimelineDuration(){validateTimelineEdit(false)}
function syncTimelineEnd(){const durationInput=$('#timeline-edit-duration'),raw=durationInput.value.trim();if(raw===''){$('#timeline-edit-preview').textContent='';$('#timeline-edit-error').textContent='请输入专注时长。';$('#timeline-edit-error').classList.remove('hidden');return}const start=timelineTimestamp($('#timeline-edit-start').value),duration=Math.round(Number(raw));if(!Number.isFinite(start)||!Number.isFinite(duration)||duration<1){$('#timeline-edit-preview').textContent='';$('#timeline-edit-error').textContent='专注时长请输入 1–1439 分钟。';$('#timeline-edit-error').classList.remove('hidden');return}const end=start+duration*60000;if(dateKey(start)!==dateKey(end)){$('#timeline-edit-error').textContent='专注记录不能跨越到第二天。';$('#timeline-edit-error').classList.remove('hidden');return}$('#timeline-edit-end').value=timelineClock(end);validateTimelineEdit(false)}
function openTimelineEdit(id){const record=state.records.find(item=>item.id===id);if(!record)return;timelineEditingId=id;selectedDate=new Date(record.end);$('#timeline-edit-task').textContent=record.task;$('#timeline-edit-start').value=timelineClock(record.start);$('#timeline-edit-end').value=timelineClock(record.end);$('#timeline-edit-duration').value=Math.max(1,mins(record.duration));$('#timeline-edit-error').classList.add('hidden');validateTimelineEdit(false);$('#timeline-edit-modal').classList.add('open')}
