$('#timeline-edit-start').oninput=syncTimelineDuration;$('#timeline-edit-end').oninput=syncTimelineDuration;$('#timeline-edit-duration').oninput=syncTimelineEnd;$('#timeline-edit-cancel').onclick=closeTimelineEdit;$('#timeline-edit-save').onclick=()=>{const candidate=validateTimelineEdit(true);if(!candidate)return;candidate.record.start=candidate.start;candidate.record.end=candidate.end;candidate.record.duration=candidate.duration*60000;save();closeTimelineEdit();renderCalendar();renderTimeline();renderStats();renderDailyRank();toast('时间轴记录已更新')};
