$('#goal-btn').onclick=openFocusGoal;$('#focus-goal-cancel').onclick=closeFocusGoal;$('#focus-goal-save').onclick=()=>{const taskHours=Number($('#task-focus-limit').value),dailyHours=Number($('#daily-rest-limit').value),error=$('#focus-goal-error');let message='';if(!Number.isFinite(taskHours)||taskHours<.25||taskHours>24)message='任务专注时长请输入 0.25–24 小时。';else if(!Number.isFinite(dailyHours)||dailyHours<1||dailyHours>24)message='总计专注时长提醒请输入 1–24 小时。';if(message){error.textContent=message;error.classList.remove('hidden');return}state.taskFocusLimit=Math.round(taskHours*60);state.dailyRestLimit=Math.round(dailyHours*60);delete state.restReminderDate;save();renderGoal();closeFocusGoal();toast('专注目标已保存')};
function renderPreferences(){const permission='Notification' in window?Notification.permission:'unsupported';$('#reminder-label').textContent=state.reminders&&permission==='granted'?'已开启　›':'已关闭　›';$('#sound-label').textContent={bell:'清脆铃声　›',soft:'柔和提示　›',mute:'静音　›'}[state.soundMode]}
$('#reminder').onclick=async()=>{if(state.reminders){state.reminders=false;save();renderPreferences();return toast('完成提醒已关闭')}if(!('Notification' in window)){state.reminders=false;renderPreferences();return alert('当前浏览器不支持网页通知。iPhone 请先将 Focus Grove 添加到主屏幕，再从桌面图标打开。')}let permission=Notification.permission;if(permission==='default')permission=await Notification.requestPermission();if(permission==='granted'){state.reminders=true;save();renderPreferences();toast('完成提醒已开启')}else{state.reminders=false;save();renderPreferences();alert('通知权限未开启。请在手机“设置”中允许此网站发送通知。')}};
$('#sound').onclick=()=>{prepareAudio();state.soundMode={bell:'soft',soft:'mute',mute:'bell'}[state.soundMode];save();renderPreferences();if(state.soundMode==='mute')toast('专注音效已设为静音');else{completionSound();toast(`已切换为${state.soundMode==='soft'?'柔和提示':'清脆铃声'}`)}};
function showDataHelp(){alert('数据保留说明\n\n【本机自动保存】\n✓ 任务、专注记录和设置会立即保存在当前设备\n✓ 断网时仍可正常使用\n\n【云端同步】\n✓ 登录后自动上传任务、记录、段位和设置\n✓ 换手机后登录同一账号即可恢复\n✓ 首次登录前会备份现有本机数据\n\n建议仍定期使用“数据导出与导入”下载独立备份。')}
function compareVersions(a,b){const aa=a.split('.').map(Number),bb=b.split('.').map(Number);for(let i=0;i<Math.max(aa.length,bb.length);i++){if((aa[i]||0)!==(bb[i]||0))return(aa[i]||0)-(bb[i]||0)}return 0}
let pendingUpdateInfo=null;
function setUpdateIndicator(available){$('#version-label').classList.toggle('has-update',available)}
function showUpdateModal(info,remember=false){if($('#update-modal').classList.contains('open')&&pendingUpdateInfo?.version===info.version)return;pendingUpdateInfo=info;if(remember)localStorage.setItem(UPDATE_PROMPT_KEY,info.version);setUpdateIndicator(true);$('#update-title').textContent=`发现新版本 v${info.version}`;$('#update-notes').textContent=info.notes||'包含功能改进和问题修复。';$('#update-modal').classList.add('open')}
async function installLatest(){if(!pendingUpdateInfo)return;const targetVersion=pendingUpdateInfo.version;state.acceptedVersion=targetVersion;state.lastSeenVersion=targetVersion;localStorage.setItem(UPDATE_PROMPT_KEY,targetVersion);localStorage.setItem(INSTALLED_VERSION_KEY,targetVersion);save();$('#update-modal').classList.remove('open');toast('正在安全更新…');if('serviceWorker' in navigator){const registration=await navigator.serviceWorker.getRegistration();if(registration){await registration.update();const waiting=registration.waiting;if(waiting){waiting.postMessage({type:'SKIP_WAITING'});await new Promise(resolve=>{navigator.serviceWorker.addEventListener('controllerchange',resolve,{once:true});setTimeout(resolve,1800)})}}}location.replace(`${location.pathname}?updated=${Date.now()}`)}
async function checkForUpdate(manual=true){if(location.protocol==='file:'){setUpdateIndicator(false);if(manual)alert(`Focus Rise v${CURRENT_VERSION}\n\n【本地预览模式】\n当前无法在线检查更新。\n发布到 GitHub Pages 后即可使用自动更新。`);return}if(manual)toast('正在检查更新…');try{const response=await fetch(`./version.json?check=${Date.now()}`,{cache:'no-store'});if(!response.ok)throw new Error('version');const info=await response.json(),installed=localStorage.getItem(INSTALLED_VERSION_KEY)||CURRENT_VERSION;if(compareVersions(info.version,CURRENT_VERSION)<=0||compareVersions(info.version,installed)<=0){setUpdateIndicator(false);if(manual)alert(`Focus Rise v${CURRENT_VERSION}\n\n✓ 当前已经是最新版本\n\n【数据状态】\n任务、专注记录和设置均安全保存在本机。`);return}setUpdateIndicator(true);if(!manual&&(state.skipUpdateVersion===info.version||localStorage.getItem(UPDATE_PROMPT_KEY)===info.version))return;showUpdateModal(info,!manual)}catch(error){if(manual)alert('检查更新失败\n\n请确认网络正常后重试。\n\n【数据状态】\n你的现有任务和专注数据不会受到影响。')}}
$('#install-update').onclick=installLatest;$('#later-update').onclick=()=>{$('#update-modal').classList.remove('open');pendingUpdateInfo=null;toast('本版本不会再次自动弹出，可在“关于与更新”中手动检查')};$('#skip-update').onclick=()=>{if(pendingUpdateInfo){state.skipUpdateVersion=pendingUpdateInfo.version;localStorage.setItem(UPDATE_PROMPT_KEY,pendingUpdateInfo.version);save()}$('#update-modal').classList.remove('open');pendingUpdateInfo=null;toast('此版本将不再提醒')};
$('#theme').onclick=()=>{state.dark=!state.dark;document.body.classList.toggle('dark',state.dark);save()};$('#about').onclick=()=>checkForUpdate(true);
const FONT_SCALE_TARGETS='.topbar h1,.topbar .eyebrow,.page[data-page="tasks"] :is(h1,h2,h3,h4,p,b,strong,span,small,em,label,button,input,select,textarea),.page[data-page="stats"] :is(h1,h2,h3,h4,p,b,strong,span,small,em,label,button,input,select,textarea),.page[data-page="forest"] :is(h1,h2,h3,h4,p,b,strong,span,small,em,label,button,input,select,textarea),.page[data-page="timeline"] :is(h1,h2,h3,h4,p,b,strong,span,small,em,label,button,input,select,textarea)';
function applyContentFontScale(){const scale={standard:1,large:1.14,xlarge:1.28}[state.fontSize]||1,elements=[...document.querySelectorAll(FONT_SCALE_TARGETS)];elements.forEach(element=>{if(!element.dataset.baseFontSize){const size=parseFloat(getComputedStyle(element).fontSize);if(Number.isFinite(size)&&size>0)element.dataset.baseFontSize=String(size)}});elements.forEach(element=>{const base=Number(element.dataset.baseFontSize);if(base)element.style.setProperty('font-size',`${Math.round(base*scale*10)/10}px`,'important')})}
function renderFontSize(){if(!['standard','large','xlarge'].includes(state.fontSize))state.fontSize='standard';document.body.classList.remove('font-large','font-xlarge');document.documentElement.dataset.fontSize=state.fontSize;if(state.fontSize==='large')document.body.classList.add('font-large');if(state.fontSize==='xlarge')document.body.classList.add('font-xlarge');applyContentFontScale();$('#font-size-label').textContent={standard:'标准　›',large:'大字　›',xlarge:'特大　›'}[state.fontSize]}
$('#font-size').onclick=()=>{state.fontSize={standard:'large',large:'xlarge',xlarge:'standard'}[state.fontSize];save();renderFontSize();toast(`已切换为${{standard:'标准字体',large:'大字体',xlarge:'特大字体'}[state.fontSize]}`)};
$('#feedback-btn').onclick=()=>$('#feedback-modal').classList.add('open');$('#close-feedback').onclick=()=>$('#feedback-modal').classList.remove('open');$('#feedback-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('#submit-feedback'),data=new FormData(form);button.disabled=true;button.textContent='正在提交…';try{const response=await fetch(form.action,{method:'POST',body:data,headers:{Accept:'application/json'}});if(!response.ok){let message='提交服务暂时不可用';try{const result=await response.json();if(result.errors?.length)message=result.errors.map(item=>item.message).join('；')}catch(error){}throw new Error(message)}form.reset();$('#feedback-modal').classList.remove('open');toast('感谢反馈，建议已发送到开发者邮箱')}catch(error){try{form.target='feedback-submit-frame';HTMLFormElement.prototype.submit.call(form);setTimeout(()=>{form.reset();form.removeAttribute('target');$('#feedback-modal').classList.remove('open');toast('反馈已通过备用通道发送，请稍后查看邮箱')},900)}catch(fallbackError){alert(`反馈未能提交：${error.message||'请检查网络后重试'}`)}}finally{setTimeout(()=>{button.disabled=false;button.textContent='提交反馈'},1000)}};
function transferableState(){const copy=JSON.parse(JSON.stringify(state));delete copy.activeTimer;return copy}
function openDataTransfer(){$('#data-import-file').value='';$('#data-transfer-modal').classList.add('open')}
async function copyTransferData(){const text=JSON.stringify(transferableState(),null,2);try{await navigator.clipboard.writeText(text);toast('数据已复制，可粘贴到其他设备')}catch(error){const field=document.createElement('textarea');field.value=text;field.style.position='fixed';field.style.opacity='0';document.body.append(field);field.select();document.execCommand('copy');field.remove();toast('数据已复制')}}
function downloadTransferData(){const blob=new Blob([JSON.stringify(transferableState(),null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`Focus-Rise-数据备份-${dateKey(new Date())}.json`;a.click();URL.revokeObjectURL(a.href);toast('备份文件已下载')}
function validateImportedState(value){if(!value||typeof value!=='object'||!Array.isArray(value.tasks)||!Array.isArray(value.records))throw new Error('这不是有效的 Focus Rise 数据');const clean={...value};clean.tasks=clean.tasks.filter(task=>task&&task.id&&typeof task.name==='string').map(task=>({...task,duration:Math.max(1,Number(task.duration)||25),projectId:task.projectId||null}));clean.records=clean.records.filter(record=>record&&Number.isFinite(Number(record.start))&&Number.isFinite(Number(record.end))&&Number.isFinite(Number(record.duration))).map(record=>({...record,start:Number(record.start),end:Number(record.end),duration:Number(record.duration),projectId:record.projectId||null,projectName:record.projectName||''}));clean.projects=Array.isArray(clean.projects)?clean.projects.filter(project=>project&&project.id&&typeof project.name==='string').map(project=>({...project,tasks:Array.isArray(project.tasks)?project.tasks.filter(task=>task&&task.id&&typeof task.name==='string').map(task=>({...task,duration:Math.max(1,Number(task.duration)||25),projectId:project.id})):[]})):[];delete clean.activeTimer;return clean}
function importTransferData(raw){try{const imported=validateImportedState(JSON.parse(raw));if(!confirm(`将导入 ${imported.tasks.length} 个待办、${imported.projects.length} 个项目夹和 ${imported.records.length} 条专注记录。\n\n导入后将替换当前数据，是否继续？`))return;localStorage.setItem(`${KEY}-before-import-${Date.now()}`,JSON.stringify(state));state=imported;if(!state.dailyGoal)state.dailyGoal=120;if(!Number.isFinite(Number(state.taskFocusLimit)))state.taskFocusLimit=120;if(!Number.isFinite(Number(state.dailyRestLimit)))state.dailyRestLimit=480;if(typeof state.reminders!=='boolean')state.reminders=false;if(!state.soundMode)state.soundMode='bell';if(!state.fontSize)state.fontSize='standard';if(!state.acceptedVersion)state.acceptedVersion=CURRENT_VERSION;save();document.body.classList.toggle('dark',!!state.dark);renderAll();$('#data-transfer-modal').classList.remove('open');toast('数据导入完成');return true}catch(error){alert(`无法导入数据\n\n${error.message||'请选择由 Focus Rise 导出的完整 JSON 文件。'}`);return false}}
function looksLikeFocusData(text){try{const value=JSON.parse(text);return value&&Array.isArray(value.tasks)&&Array.isArray(value.records)}catch(error){return false}}
async function importFromClipboardOrFile(){const button=$('#import-data'),original=button.textContent;button.disabled=true;button.textContent='正在识别剪贴板…';try{if(navigator.clipboard?.read){const items=await navigator.clipboard.read();for(const item of items){for(const type of item.types){if(type==='text/plain'||type.includes('json')){const text=await(await item.getType(type)).text();if(looksLikeFocusData(text)){importTransferData(text);return}}}}}if(navigator.clipboard?.readText){const text=await navigator.clipboard.readText();if(looksLikeFocusData(text)){importTransferData(text);return}}}catch(error){}finally{button.disabled=false;button.textContent=original}toast('剪贴板中未识别到数据，请选择 JSON 备份文件');$('#data-import-file').click()}
$('#export').onclick=openDataTransfer;$('#copy-data').onclick=copyTransferData;$('#download-data').onclick=downloadTransferData;$('#import-data').onclick=importFromClipboardOrFile;$('#data-import-file').onchange=async event=>{const file=event.target.files?.[0];if(!file)return;if(!/\.json$/i.test(file.name))return alert('请选择名称以 .json 结尾的专注数据备份文件。');if(file.size>10*1024*1024)return alert('备份文件过大，无法导入。');importTransferData(await file.text())};$('#data-transfer-close').onclick=()=>$('#data-transfer-modal').classList.remove('open');
function renderAll(){renderTasks();renderStats();renderForest();renderCalendar();renderTimeline();renderGoal();renderPreferences();renderFontSize()}document.body.classList.toggle('dark',state.dark);renderAll();let fontScaleQueued=false;new MutationObserver(()=>{if(fontScaleQueued)return;fontScaleQueued=true;requestAnimationFrame(()=>{fontScaleQueued=false;applyContentFontScale()})}).observe(document.querySelector('.app-shell'),{childList:true,subtree:true});

