$('#install-app').onclick=async()=>{if(isInstalled())return toast('Focus Grove 已经安装在桌面');if(installPrompt){installPrompt.prompt();const choice=await installPrompt.userChoice;if(choice.outcome==='accepted')$('#install-label').textContent='已安装';installPrompt=null;return}const isiOS=/iphone|ipad|ipod/i.test(navigator.userAgent);if(isiOS)alert('iPhone 安装步骤：\n\n1. 请使用 Safari 打开本网页\n2. 点击底部“分享”按钮（方框向上箭头）\n3. 向下滑动并选择“添加到主屏幕”\n4. 点击右上角“添加”\n\n苹果系统不允许网页自动完成最后一步。');else alert('请打开浏览器右上角菜单，选择“安装应用”或“添加到主屏幕”。如果没有此选项，请使用最新版 Chrome 打开。')};
