const guideSlides=[
  {icon:'◆',title:'欢迎来到 Focus Rise',text:'把每一次专注变成看得见的段位进阶。接下来用一分钟认识主要功能。'},
  {icon:'＋',title:'添加与编辑任务',text:'点击待办页右上角“＋”添加任务或项目夹。轻点“我的任务”中的任务即可编辑名称、项目分类与计时方式。'},
  {icon:'↕️',title:'拖动任务排序',text:'长按并拖动任务左侧“⠿”手柄进行排序。卡片浮起后上下移动，空白区域会提示即将放置的位置。'},
  {icon:'▣',title:'使用项目夹',text:'项目夹可以集中保存相关任务。项目任务既能直接开始计时，也能点击“＋”加入“我的任务”；数据页可按项目查看专注分布。'},
  {icon:'⏱️',title:'开始一次专注',text:'点击任务右侧播放按钮开始计时。计时中可以暂停或完成，完成后的记录会自动进入数据统计。'},
  {icon:'◈',title:'提升荣誉段位',text:'“数据”查看时长与分布，“段位”查看进阶、战绩和徽章，“时间轴”回顾每一次专注。'},
  {icon:'☁',title:'登录并同步云端',text:'在“我的”登录账号，现有任务和专注记录会自动上传。换设备后登录同一邮箱即可恢复数据。'},
  {icon:'⚙️',title:'设置与安全更新',text:'在“我的”设置目标、提醒、音效和深色模式。“关于与更新”可以检查新版，更新不会删除专注数据。'}
];
let guideIndex=0;
function renderGuide(){const slide=guideSlides[guideIndex];$('#guide-icon').textContent=slide.icon;$('#guide-step').textContent=`${guideIndex+1} / ${guideSlides.length}`;$('#guide-title').textContent=slide.title;$('#guide-text').textContent=slide.text;$('#guide-dots').innerHTML=guideSlides.map((_,i)=>`<i class="${i===guideIndex?'active':''}"></i>`).join('');$('#guide-prev').style.visibility=guideIndex?'visible':'hidden';$('#guide-next').textContent=guideIndex===guideSlides.length-1?'开始使用':'下一步'}
function startGuide(){guideIndex=0;renderGuide();$('#guide-modal').classList.add('open')}
function finishGuide(){state.onboardingDone=true;state.lastSeenVersion=CURRENT_VERSION;save();$('#guide-modal').classList.remove('open');toast('随时可在“我的 → 使用教学”重新查看')}
$('#guide-next').onclick=()=>{if(guideIndex<guideSlides.length-1){guideIndex++;renderGuide()}else finishGuide()};$('#guide-prev').onclick=()=>{if(guideIndex>0){guideIndex--;renderGuide()}};$('#guide-skip').onclick=finishGuide;$('#guide-btn').onclick=startGuide;
window.addEventListener('load',()=>{if(!state.onboardingDone)setTimeout(startGuide,450)});

// Supabase 云端账户与同步。离线时仍优先保存在本机，恢复网络后自动补传。
function cloudMessage(error){const text=String(error?.message||error||'');if(/invalid login credentials/i.test(text))return'邮箱或密码不正确';if(/email not confirmed/i.test(text))return'请先打开验证邮件完成确认';if(/already registered/i.test(text))return'这个邮箱已经注册，请直接登录';if(/password/i.test(text)&&/least/i.test(text))return'密码长度至少为 6 位';if(/fetch|network/i.test(text))return'网络连接失败，请稍后重试';return text||'操作失败，请稍后重试'}
function renderCloudStatus(message=''){const signedIn=!!currentUser,email=currentUser?.email||'';$('#profile-name').textContent=signedIn?(email.split('@')[0]||'Focus Riser'):'Focus Riser';$('#profile-subtitle').textContent=signedIn?email:'每一次专注，都是一次进阶';$('#login-btn').textContent=signedIn?'账号':'登录';$('#cloud-title').textContent=signedIn?'云端已连接':'云端同步';$('#cloud-status').textContent=message||(signedIn?(lastCloudSync?`已同步 · ${lastCloudSync.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}`:'正在读取云端数据…'):'登录后跨设备保存任务、记录和段位');$('#cloud-sync').textContent=signedIn?(cloudSyncing?'同步中':'同步'):'登录';$('#auth-signed-out').classList.toggle('hidden',signedIn);$('#auth-signed-in').classList.toggle('hidden',!signedIn);$('#auth-title').textContent=signedIn?'Focus Rise 账号':'登录 Focus Rise';$('#auth-copy').textContent=signedIn?'你的专注数据会在每次修改后自动同步。':'登录后，任务、专注记录、段位和设置会安全同步到云端。';if(signedIn){$('#auth-user-email').textContent=email;$('#auth-sync-detail').textContent=message||(lastCloudSync?`最近同步：${lastCloudSync.toLocaleString('zh-CN')}`:'云端已连接')}}
function openAuth(){renderCloudStatus();$('#auth-modal').classList.add('open');setTimeout(()=>{if(!currentUser)$('#auth-email').focus()},120)}
function closeAuth(){$('#auth-modal').classList.remove('open')}
function scheduleCloudSync(){clearTimeout(cloudSyncTimer);cloudSyncTimer=setTimeout(()=>uploadCloudState(false),1200)}
function normalizedCloudState(remote){const merged={...state,...remote};merged.tasks=Array.isArray(remote?.tasks)?remote.tasks:state.tasks;merged.records=Array.isArray(remote?.records)?remote.records:state.records;merged.projects=Array.isArray(remote?.projects)?remote.projects:(state.projects||[]);if(!merged.dailyGoal)merged.dailyGoal=120;if(!Number.isFinite(Number(merged.taskFocusLimit)))merged.taskFocusLimit=120;if(!Number.isFinite(Number(merged.dailyRestLimit)))merged.dailyRestLimit=480;if(!merged.soundMode)merged.soundMode='bell';if(!merged.fontSize)merged.fontSize='standard';if(typeof merged.reminders!=='boolean')merged.reminders=false;return merged}
async function uploadCloudState(showMessage=true){if(!supabaseClient||!currentUser||cloudSyncing)return false;if(!navigator.onLine){renderCloudStatus('当前离线，联网后将自动同步');if(showMessage)toast('当前离线，数据已保存在本机');return false}cloudSyncing=true;renderCloudStatus('正在上传数据…');try{const payload=JSON.parse(JSON.stringify(state));const {error}=await supabaseClient.from('user_data').upsert({user_id:currentUser.id,data:payload,updated_at:new Date().toISOString()},{onConflict:'user_id'});if(error)throw error;lastCloudSync=new Date();renderCloudStatus();if(showMessage)toast('云端同步完成');return true}catch(error){renderCloudStatus(`同步失败：${cloudMessage(error)}`);if(showMessage)alert(`云端同步失败\n\n${cloudMessage(error)}\n\n数据仍安全保存在当前设备。`);return false}finally{cloudSyncing=false;renderCloudStatus()}}
function stateDataScore(value){return(Array.isArray(value?.records)?value.records.length*4:0)+(Array.isArray(value?.tasks)?value.tasks.length:0)+(Array.isArray(value?.projects)?value.projects.reduce((sum,project)=>sum+1+(project.tasks?.length||0),0):0)}
async function loadCloudState(){if(!supabaseClient||!currentUser)return;renderCloudStatus('正在读取云端数据…');try{const {data,error}=await supabaseClient.from('user_data').select('data, updated_at').eq('user_id',currentUser.id).maybeSingle();if(error)throw error;if(data?.data){const backupKey=`${KEY}-before-cloud-${currentUser.id}`;localStorage.setItem(backupKey,JSON.stringify(state));const remote=data.data,localScore=stateDataScore(state),remoteScore=stateDataScore(remote),localUpdated=Number(state._updatedAt)||0,remoteUpdated=Number(remote._updatedAt)||new Date(data.updated_at||0).getTime();if(localScore>remoteScore&&(!localUpdated||localUpdated>=remoteUpdated)){await uploadCloudState(false);toast('已保留并上传当前设备的完整数据');return}cloudApplying=true;state=normalizedCloudState(remote);localStorage.setItem(KEY,JSON.stringify(state));localStorage.setItem(`${KEY}-backup`,JSON.stringify(state));cloudApplying=false;document.body.classList.toggle('dark',!!state.dark);lastCloudSync=data.updated_at?new Date(data.updated_at):new Date();renderAll();renderCloudStatus();toast('云端数据已恢复')}else{await uploadCloudState(false);toast('本机数据已上传到云端')}}catch(error){cloudApplying=false;renderCloudStatus(`连接失败：${cloudMessage(error)}`);alert(`暂时无法读取云端数据\n\n${cloudMessage(error)}\n\n你仍可继续使用，本机数据不会丢失。`)}}
async function applyCloudSession(session){const nextUser=session?.user||null,changed=nextUser?.id!==currentUser?.id;currentUser=nextUser;renderCloudStatus();if(currentUser&&changed)await loadCloudState()}
async function initCloud(){renderCloudStatus('正在连接云端…');if(!window.supabase?.createClient){renderCloudStatus('云端组件加载失败，本机保存仍可使用');return}try{supabaseClient=window.supabase.createClient(SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});const {data:{session}}=await supabaseClient.auth.getSession();await applyCloudSession(session);supabaseClient.auth.onAuthStateChange((event,nextSession)=>{if(event==='SIGNED_OUT'||nextSession?.user?.id!==currentUser?.id)setTimeout(()=>applyCloudSession(nextSession),0)});if(!session)renderCloudStatus()}catch(error){renderCloudStatus(`云端连接失败：${cloudMessage(error)}`)}}
async function authCredentials(){const email=$('#auth-email').value.trim(),password=$('#auth-password').value;if(!email||!email.includes('@'))throw new Error('请输入正确的邮箱地址');if(password.length<6)throw new Error('密码长度至少为 6 位');return{email,password}}
async function runAuth(button,action){if(!supabaseClient)return alert('云端服务尚未连接，请检查网络后重试。');const original=button.textContent;button.disabled=true;button.textContent='请稍候…';try{await action()}catch(error){alert(cloudMessage(error))}finally{button.disabled=false;button.textContent=original}}
$('#auth-login').onclick=()=>runAuth($('#auth-login'),async()=>{const {email,password}=await authCredentials(),{error}=await supabaseClient.auth.signInWithPassword({email,password});if(error)throw error;toast('登录成功');closeAuth()});
$('#auth-register').onclick=()=>runAuth($('#auth-register'),async()=>{const {email,password}=await authCredentials(),redirect=location.protocol==='file:'?undefined:`${location.origin}${location.pathname}`;const {data,error}=await supabaseClient.auth.signUp({email,password,options:redirect?{emailRedirectTo:redirect}:undefined});if(error)throw error;if(data.session){toast('注册成功');closeAuth()}else alert('注册申请已提交\n\n请打开邮箱中的验证邮件，点击确认链接后再回来登录。')});
$('#auth-logout').onclick=()=>runAuth($('#auth-logout'),async()=>{await uploadCloudState(false);const {error}=await supabaseClient.auth.signOut();if(error)throw error;currentUser=null;lastCloudSync=null;renderCloudStatus();closeAuth();toast('已退出登录，本机数据仍然保留')});
$('#auth-sync-now').onclick=()=>uploadCloudState(true);
$('#auth-close').onclick=closeAuth;
$('#login-btn').onclick=openAuth;
$('#data-notice').onclick=()=>currentUser?uploadCloudState(true):openAuth();
window.addEventListener('online',()=>{if(currentUser)uploadCloudState(false)});
window.addEventListener('offline',()=>{if(currentUser)renderCloudStatus('当前离线，数据会继续保存在本机')});
window.addEventListener('load',()=>setTimeout(initCloud,250));

// 页面真正退出或刷新时立即结束本次计时，并先同步写入本机；下次打开后再补传云端。
function saveRunningTimerOnExit(){if(!timerState||timerState.exitSaved)return;timerState.exitSaved=true;const end=Date.now(),elapsed=timerState.elapsed+(timerState.running?end-timerState.start:0);clearInterval(timer);if(elapsed>=5000)state.records.push({id:uid(),taskId:timerState.task.id,task:timerState.task.name,start:end-elapsed,end,duration:elapsed});delete state.activeTimer;timerState=null;localStorage.setItem(KEY,JSON.stringify(state))}
window.addEventListener('pagehide',saveRunningTimerOnExit,{capture:true});
window.addEventListener('beforeunload',saveRunningTimerOnExit,{capture:true});
